import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia}from'./comum.js';
const lista=v=>Array.isArray(v)?v:v==null?[]:[v];
function autores(doc){return lista(doc?.authors||doc?.author).map(a=>typeof a==='object'?(a.name||a.authtype||''):a).map(String).filter(Boolean)}
export function converterNcbi(doc,id){const titulo=String(doc?.title||doc?.booktitle||'Sem título').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim(),acc=String(doc?.bookaccession||doc?.accession||doc?.bookacc||'').trim(),ler=endereco(acc?`https://www.ncbi.nlm.nih.gov/books/${encodeURIComponent(acc)}/`:`https://www.ncbi.nlm.nih.gov/books/?term=${encodeURIComponent(titulo)}`);if(!ler)return null;const desc=[doc?.pubdate,doc?.publisher,doc?.doctype].filter(Boolean).map(String).join(' · ');return{id:`ncbi:${id}`,fonte:'ncbi',provedor:'NCBI Bookshelf · NIH/NLM',titulo,autores:autores(doc),idiomas:[],capa:null,descricao:desc,acessoLivre:true,dominioPublico:false,tipoAcesso:'Livro / capítulo biomédico · leitura gratuita',licenca:'O NCBI Bookshelf oferece acesso online gratuito. Direitos autorais e permissões variam por título e são informados na própria obra.',origem:ler,ler,texto:null,formatos:[]}}
export async function pesquisarNcbiBookshelf(q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','ncbi');u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));const busca=await obterJSON(u,14000,2),r=busca?.esearchresult||{},ids=Array.isArray(r.idlist)?r.idlist.map(String).filter(Boolean):[],total=Number(r.count)||ids.length;if(!ids.length)return{livros:[],total,temMais:false};const s=new URL('/api/acervos-gratuitos',location.origin);s.searchParams.set('fonte','ncbi-resumo');s.searchParams.set('q',ids.join(','));s.searchParams.set('pagina','1');const resumo=await obterJSON(s,14000,2),dados=resumo?.result||{},livros=ids.map(id=>converterNcbi(dados[id]||{},id)).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));return{livros,total,temMais:pagina*15<total&&ids.length>0}}
